// src/App.js
import React, { useState } from 'react';
import { GoogleOAuthProvider, GoogleLogin } from '@react-oauth/google';
import { jwtDecode } from "jwt-decode";
import axios from 'axios';
import { MapContainer, TileLayer, GeoJSON } from 'react-leaflet';
import worldGeoJSON from './world.geo.json'; // Make sure you have this file
import './App.css'; // We'll create this file next

// --- IMPORTANT ---
// 1. Get your Google Client ID from https://console.cloud.google.com/
// 2. Make sure it's authorized for "http://localhost:3000"
const GOOGLE_CLIENT_ID = "1036961205522-rmp3m6400riqi59m0ft3gnfg8pubbg9c.apps.googleusercontent.com";
const BACKEND_URL = "http://localhost:8000";

function App() {
    const [user, setUser] = useState(null);
    const [query, setQuery] = useState('');
    const [mapData, setMapData] = useState([]);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    const handleSearch = async (e) => {
        e.preventDefault();
        if (!user) return;
        setLoading(true);
        setError('');
        setMapData([]);

        try {
            const response = await axios.post(`${BACKEND_URL}/api/query`, { query });
            setMapData(response.data);
        } catch (err) {
            setError(err.response?.data?.detail || "An unexpected error occurred.");
        } finally {
            setLoading(false);
        }
    };

    // --- Map Styling Logic ---
    const dataMap = new Map(mapData.map(item => [item.country_code, item.value]));
    const maxValue = Math.max(...mapData.map(item => item.value || 0));

    const getColor = (value) => {
        if (!value) return '#CCCCCC'; // Gray for no data
        const intensity = value / maxValue;
        if (intensity > 0.8) return '#800026';
        if (intensity > 0.6) return '#BD0026';
        if (intensity > 0.4) return '#E31A1C';
        if (intensity > 0.2) return '#FC4E2A';
        return '#FD8D3C';
    };

    const mapStyle = (feature) => ({
        fillColor: getColor(dataMap.get(feature.id)),
        weight: 1,
        opacity: 1,
        color: 'white',
        fillOpacity: 0.7
    });

    return (
        <GoogleOAuthProvider clientId={GOOGLE_CLIENT_ID}>
            <div className="app-container">
                {/* --- TOP BAR: LOGIN & SEARCH --- */}
                <div className="top-bar">
                    <h1>DataMap</h1>
                    <div className="search-area">
                        {user && (
                            <form onSubmit={handleSearch}>
                                <input
                                    type="text"
                                    value={query}
                                    onChange={(e) => setQuery(e.target.value)}
                                    placeholder="e.g., Which countries have the highest GDP?"
                                />
                                <button type="submit" disabled={loading}>
                                    {loading ? '...' : 'Search'}
                                </button>
                            </form>
                        )}
                    </div>
                    <div className="login-area">
                        {user ? (
                            <div className="welcome-message">Welcome, {user.given_name}!</div>
                        ) : (
                            <GoogleLogin
                                onSuccess={(res) => setUser(jwtDecode(res.credential))}
                                onError={() => console.log('Login Failed')}
                            />
                        )}
                    </div>
                </div>

                 {/* --- NOTIFICATION AREA --- */}
                {error && <div className="error-banner">{error}</div>}

                {/* --- MAP DISPLAY --- */}
                <MapContainer center={[20, 0]} zoom={2} style={{ height: '100vh', width: '100%', zIndex: 0 }}>
                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                    <GeoJSON
                        key={JSON.stringify(mapData)} // Force re-render when data changes
                        data={worldGeoJSON}
                        style={mapStyle}
                        onEachFeature={(feature, layer) => {
                            const value = dataMap.get(feature.id);
                            const label = mapData.length > 0 ? mapData[0].label : '';
                            layer.bindPopup(`<strong>${feature.properties.name}</strong><br/>${label}: ${value ? value.toLocaleString() : 'No data'}`);
                        }}
                    />
                </MapContainer>
            </div>
        </GoogleOAuthProvider>
    );
}

export default App;
